1	//! Recurrent state for Qwen3.5 linear attention layers.
2	//!
3	//! Each linear attention layer maintains:
4	//! - Recurrent state: [local_value_heads, key_head_dim, value_head_dim] f32, V contiguous ([H,K,V])
5	//! - Conv state: [local_qkv_dim × (conv_kernel_dim - 1)] bf16
6	//!
7	//! Under TP, value heads (and fused qkv channels) are sharded across ranks,
8	//! so every rank owns its own recurrent/conv state; these states are never
9	//! all-reduced.
10	
11	use anyhow::Result;
12	use cudarc::driver::CudaSlice;
13	use cudarc::driver::DevicePtrMut;
14	use pegainfer_core::tensor::DeviceContext;
15	use pegainfer_core::tensor::DeviceVec;
16	
17	use super::config::Config35;
18	use super::config::LocalGeometry;
19	
20	/// Per-layer recurrent state for a single linear attention layer.
21	pub(crate) struct LayerRecurrentState {
22	    /// Recurrent state matrix: [local_value_heads * key_head_dim * value_head_dim] f32
23	    /// Stored as f32 per mamba_ssm_dtype="float32" in config.
24	    pub(crate) state: CudaSlice<f32>,
25	    /// Conv1d state buffer: [local_linear_qkv_dim * (conv_kernel_dim - 1)] bf16
26	    /// Stores the last (kernel_dim - 1) inputs for causal conv1d.
27	    pub(crate) conv_state: DeviceVec,
28	}
29	
30	/// Recurrent state for all linear attention layers.
31	pub(crate) struct RecurrentState {
32	    pub(crate) layers: Vec<LayerRecurrentState>,
33	    /// Number of tokens processed so far (for prefill/decode tracking).
34	    pub(crate) seq_len: usize,
35	}
36	
37	/// Device-side tables of per-slot recurrent-state pointers.
38	///
39	/// Batched linear decode kernels take a device array of pointers per linear
40	/// layer. The underlying `CudaSlice` allocations inside `RecurrentState` stay
41	/// at fixed device addresses for the request lifetime, so these tables should
42	/// be built once per slot/request and then reused across decode tokens.
43	///
44	/// Where the row set changes between steps (eager TP decode), allocate once at
45	/// capacity with `with_capacity` and `refill_from_recurrent_refs` the live
46	/// rows each step: H2D copies into the existing tables, no per-step allocation.
47	pub(crate) struct LinearStatePointerTables {
48	    pub(crate) state_ptrs: Vec<CudaSlice<u64>>,
49	    pub(crate) conv_state_ptrs: Vec<CudaSlice<u64>>,
50	    capacity: usize,
51	}
52	
53	/// Per-layer element counts shared by allocation and reservation:
54	/// (linear layers, f32 state elements, bf16 conv elements).
55	fn per_layer_dims(config: &Config35, geometry: LocalGeometry) -> (usize, usize, usize) {
56	    let num_linear_layers = config.num_hidden_layers - config.num_full_attention_layers();
57	    let state_size = geometry.local_linear_num_value_heads()
58	        * config.linear_key_head_dim
59	        * config.linear_value_head_dim;
60	    let conv_state_size = geometry.local_linear_qkv_dim() * (config.linear_conv_kernel_dim - 1);
61	    (num_linear_layers, state_size, conv_state_size)
62	}
63	
64	impl RecurrentState {
65	    /// Allocate zeroed recurrent state for all linear attention layers.
66	    pub(crate) fn new(
67	        ctx: &DeviceContext,
68	        config: &Config35,
69	        geometry: LocalGeometry,
70	    ) -> Result<Self> {
71	        let (num_linear_layers, state_size, conv_state_size) = per_layer_dims(config, geometry);
72	
73	        let mut layers = Vec::with_capacity(num_linear_layers);
74	        for _ in 0..num_linear_layers {
75	            let state: CudaSlice<f32> = ctx
76	                .stream
77	                .alloc_zeros(state_size)
78	                .map_err(|e| anyhow::anyhow!("Alloc recurrent state failed: {}", e))?;
79	            layers.push(LayerRecurrentState {
80	                state,
81	                conv_state: DeviceVec::zeros(ctx, conv_state_size)?,
82	            });
83	        }
84	
85	        Ok(Self { layers, seq_len: 0 })
86	    }
87	}
88	
89	impl LinearStatePointerTables {
90	    /// Allocate zeroed per-layer tables with room for `capacity` rows. Rows
91	    /// carry no pointers until `refill_from_recurrent_refs` writes them.
92	    pub(crate) fn with_capacity(
93	        ctx: &DeviceContext,
94	        config: &Config35,
95	        capacity: usize,
96	        label: &str,
97	    ) -> Result<Self> {
98	        let num_linear_layers = config.num_hidden_layers - config.num_full_attention_layers();
99	        let mut state_ptrs = Vec::with_capacity(num_linear_layers);
100	        let mut conv_state_ptrs = Vec::with_capacity(num_linear_layers);
101	        for layer_idx in 0..num_linear_layers {
102	            state_ptrs.push(ctx.stream.alloc_zeros::<u64>(capacity).map_err(|e| {
103	                anyhow::anyhow!("alloc {label} linear state pointer table {layer_idx}: {e}")
104	            })?);
105	            conv_state_ptrs.push(ctx.stream.alloc_zeros::<u64>(capacity).map_err(|e| {
106	                anyhow::anyhow!("alloc {label} conv state pointer table {layer_idx}: {e}")
107	            })?);
108	        }
109	        Ok(Self {
110	            state_ptrs,
111	            conv_state_ptrs,
112	            capacity,
113	        })
114	    }
115	
116	    /// Tables sized exactly to `batch_size` rows, filled once.
117	    pub(crate) fn from_recurrent_refs(
118	        ctx: &DeviceContext,
119	        config: &Config35,
120	        recurrent_states: &mut [&mut RecurrentState],
121	        batch_size: usize,
122	        label: &str,
123	    ) -> Result<Self> {
124	        let mut tables = Self::with_capacity(ctx, config, batch_size, label)?;
125	        tables.refill_from_recurrent_refs(ctx, recurrent_states, batch_size, label)?;
126	        Ok(tables)
127	    }
128	
129	    /// Overwrite rows `0..batch_size` of every layer table with the current
130	    /// state addresses of `recurrent_states`. Copies into the existing
131	    /// allocations only; rows past `batch_size` keep whatever they held and
132	    /// must stay unaddressed (the kernels are handed `batch_size`).
133	    pub(crate) fn refill_from_recurrent_refs(
134	        &mut self,
135	        ctx: &DeviceContext,
136	        recurrent_states: &mut [&mut RecurrentState],
137	        batch_size: usize,
138	        label: &str,
139	    ) -> Result<()> {
140	        anyhow::ensure!(
141	            batch_size <= recurrent_states.len(),
142	            "{label} pointer table batch {batch_size} exceeds recurrent refs {}",
143	            recurrent_states.len()
144	        );
145	        anyhow::ensure!(
146	            batch_size <= self.capacity,
147	            "{label} pointer table batch {batch_size} exceeds capacity {}",
148	            self.capacity
149	        );
150	        let tables = self
151	            .state_ptrs
152	            .iter_mut()
153	            .zip(self.conv_state_ptrs.iter_mut());
154	        for (layer_idx, (state_table, conv_table)) in tables.enumerate() {
155	            let mut state_ptrs = Vec::with_capacity(batch_size);
156	            let mut conv_state_ptrs = Vec::with_capacity(batch_size);
157	            for slot in recurrent_states.iter_mut().take(batch_size) {
158	                let state_ptr = {
159	                    let (ptr, _guard) = slot.layers[layer_idx].state.device_ptr_mut(&ctx.stream);
160	                    ptr
161	                };
162	                let conv_ptr = {
163	                    let (ptr, _guard) = slot.layers[layer_idx]
164	                        .conv_state
165	                        .data
166	                        .device_ptr_mut(&ctx.stream);
167	                    ptr
168	                };
169	                state_ptrs.push(state_ptr);
170	                conv_state_ptrs.push(conv_ptr);
171	            }
172	            ctx.stream
173	                .memcpy_htod(state_ptrs.as_slice(), state_table)
174	                .map_err(|e| {
175	                    anyhow::anyhow!("copy {label} linear state pointer table {layer_idx}: {e}")
176	                })?;
177	            ctx.stream
178	                .memcpy_htod(conv_state_ptrs.as_slice(), conv_table)
179	                .map_err(|e| {
180	                    anyhow::anyhow!("copy {label} conv state pointer table {layer_idx}: {e}")
181	                })?;
182	        }
183	        Ok(())
184	    }
185	
186	    pub(crate) fn validate_for(
187	        &self,
188	        config: &Config35,
189	        batch_size: usize,
190	        label: &str,
191	    ) -> Result<()> {
192	        let num_linear_layers = config.num_hidden_layers - config.num_full_attention_layers();
193	        anyhow::ensure!(
194	            self.capacity >= batch_size,
195	            "{label} pointer table capacity {} is smaller than batch {batch_size}",
196	            self.capacity
197	        );
198	        anyhow::ensure!(
199	            self.state_ptrs.len() == num_linear_layers
200	                && self.conv_state_ptrs.len() == num_linear_layers,
201	            "{label} pointer table layer count mismatch: state={}, conv={}, expected={num_linear_layers}",
202	            self.state_ptrs.len(),
203	            self.conv_state_ptrs.len()
204	        );
205	        Ok(())
206	    }
207	}
208	
209	/// Device bytes of one request's recurrent state.
210	pub(crate) fn bytes_per_request(config: &Config35, geometry: LocalGeometry) -> usize {
211	    let (num_linear_layers, state_size, conv_state_size) = per_layer_dims(config, geometry);
212	    num_linear_layers
213	        * (state_size * std::mem::size_of::<f32>()
214	            + conv_state_size * std::mem::size_of::<half::bf16>())
215	}
216	
217	impl RecurrentState {
218	    pub(crate) fn allocation_bytes(config: &Config35, geometry: LocalGeometry) -> usize {
219	        bytes_per_request(config, geometry)
220	    }
221	}
222	
223	#[cfg(test)]
224	mod tests {
225	    #[test]
226	    fn qwen35_4b_recurrent_allocation_is_49_125_mib() {
227	        let bytes = 24
228	            * (32 * 128 * 128 * std::mem::size_of::<f32>()
229	                + 8192 * 3 * std::mem::size_of::<half::bf16>());
230	        assert_eq!(bytes, 49 * 1024 * 1024 + 128 * 1024);
231	    }
232	}
