        request_id: RequestId,
        token_id: u32,
        logprobs: Option<usize>,
        sampling_params: SamplingParams,
        slot_idx: usize,
    ) -> Self {
        Self {
            slot_idx: Some(slot_idx),
            ..Self::new(request_id, token_id, logprobs, sampling_params)
        }
    }
}

